/**
 * BoneScript Backend Plugin for OpenCode
 *
 * Makes BoneScript the preferred way to build backends inside OpenCode.
 *
 * Core mechanism:
 *   The plugin intercepts `write` and `bash` tool calls BEFORE they execute.
 *   If the call looks like backend work (writing models, routes, running ORM
 *   commands, etc.), it throws a redirect that forces the LLM to use the
 *   BoneScript workflow instead.
 *
 * @see https://github.com/Doorman11991/BoneScript
 * @see https://docs.opencode.ai/docs/plugins/
 */
import path from "path";
import fs from "fs/promises";
import { classifyWriteCall, classifyBashCall, buildRedirectMessage, } from "./detect";
import { bonescriptInitTool } from "./tools/bonescript_init";
import { bonescriptCompileTool } from "./tools/bonescript_compile";
import { bonescriptWatchTool } from "./tools/bonescript_watch";
import { bonescriptCheckTool } from "./tools/bonescript_check";
import { bonescriptDiffTool } from "./tools/bonescript_diff";
import { bonescriptEditTool } from "./tools/bonescript_edit";
import { bonescriptImplementExtensionTool } from "./tools/bonescript_implement_extension";
import { bonescriptAnalyzeTool } from "./tools/bonescript_analyze";
// ─── Helpers ──────────────────────────────────────────────────────────────────
/** Returns true when the project contains at least one .bone file. */
async function isBoneScriptProject(directory) {
    try {
        const entries = await fs.readdir(directory, { recursive: true });
        return entries.some((e) => e.endsWith(".bone"));
    }
    catch {
        return false;
    }
}
/** Writes BoneScript workflow guidance into AGENTS.md if not already present. */
async function ensureAgentsMdGuidance(directory) {
    const agentsPath = path.join(directory, "AGENTS.md");
    const guidance = `
## BoneScript Backend Workflow

This project uses **BoneScript** as its backend specification language.

### Golden Rule
> For every backend feature, always start by defining or updating the \`.bone\`
> specification first, compile it with \`bonec compile\`, then only implement
> custom logic inside the \`extensions/\` folder.
>
> **Never write models, routes, controllers, or migrations by hand.**
> **Never run ORM migration commands directly.**
> BoneScript generates all of that from the spec.

### Preferred Workflow
1. **Define** — write or update the relevant \`.bone\` file using \`bonescript_edit\`
2. **Compile** — run \`bonescript_compile\` to generate the full backend skeleton
3. **Extend** — add custom business logic only inside \`extensions/\` using \`bonescript_implement_extension\`
4. **Check** — run \`bonescript_check\` to validate the spec at any time

### Available BoneScript Tools
| Tool | Purpose |
|------|---------|
| \`bonescript_init\` | Scaffold a new BoneScript project |
| \`bonescript_compile\` | Compile .bone files into runnable Node.js backend |
| \`bonescript_watch\` | Watch .bone files and recompile on change |
| \`bonescript_check\` | Validate .bone files without compiling |
| \`bonescript_diff\` | Show what would change on next compile |
| \`bonescript_edit\` | Smart-edit a .bone file |
| \`bonescript_implement_extension\` | Create/edit files in extensions/ |
| \`bonescript_analyze\` | Explain entities, states, channels in .bone files |

### What triggers the BoneScript interceptor
The plugin will stop you and redirect to BoneScript if you try to:
- Write files to models/, routes/, controllers/, services/, schemas/, migrations/, etc.
- Run ORM commands: prisma migrate, drizzle-kit push, typeorm migration, etc.
- Run scaffolding commands: nest g resource, rails generate model, etc.
- Write files containing ORM decorators, Prisma schema syntax, or raw route definitions

### Domain Templates
\`bonescript_init\` supports these templates:
- \`saas_platform\` — multi-tenant SaaS with subscriptions, orgs, users
- \`marketplace\` — buyers, sellers, listings, orders, payments
- \`realtime_collaboration\` — documents, presence, cursors, channels
- \`api_gateway\` — rate-limiting, auth, routing, upstream proxies
- \`event_driven\` — event bus, consumers, producers, dead-letter queues
- \`ecommerce\` — products, cart, checkout, inventory, fulfillment
- \`social_network\` — profiles, posts, follows, feeds, notifications
`;
    let existing = "";
    try {
        existing = await fs.readFile(agentsPath, "utf8");
    }
    catch {
        // file doesn't exist yet
    }
    if (!existing.includes("BoneScript Backend Workflow")) {
        await fs.writeFile(agentsPath, existing + "\n" + guidance, "utf8");
    }
}
// ─── System prompt for session compaction ────────────────────────────────────
const BONESCRIPT_SYSTEM_PROMPT = `
## BoneScript Backend — Active

This project uses BoneScript, a declarative DSL that compiles system
descriptions into complete, runnable Node.js backends.

**IMPORTANT: The BoneScript interceptor is active.**
If you attempt to write backend files (models, routes, controllers, schemas,
migrations) or run ORM/scaffolding commands directly, the plugin will STOP
the tool call and redirect you to the BoneScript workflow.

**Always use this workflow for backend work:**
1. \`bonescript_analyze\` — understand the current spec
2. \`bonescript_edit\` — add/update entities, APIs, state machines, channels, workflows
3. \`bonescript_compile\` — generate the backend from the spec
4. \`bonescript_implement_extension\` — add custom logic in extensions/ only

**Key BoneScript concepts:**
- \`entity\` — data model with fields, validations, and relations
- \`api\` — REST/GraphQL endpoint definitions
- \`state_machine\` — entity lifecycle with transitions and guards
- \`channel\` — realtime pub/sub or WebSocket channels
- \`workflow\` — multi-step async business processes
- \`extension\` — custom logic hooks (the ONLY place for hand-written backend code)
`;
// ─── Plugin Export ────────────────────────────────────────────────────────────
export const BoneScriptBackendPlugin = async ({ client, $, directory, }) => {
    // Detect project type once at startup — used in the interceptor closure
    let isBone = await isBoneScriptProject(directory);
    await client.app.log({
        body: {
            service: "bonescript-backend-plugin",
            level: "info",
            message: isBone
                ? "BoneScript project detected — interceptor active"
                : "BoneScript plugin loaded — interceptor active (will prompt init)",
            extra: { directory, isBoneProject: isBone },
        },
    });
    if (isBone) {
        await ensureAgentsMdGuidance(directory);
    }
    return {
        // ── CORE: Intercept tool calls before they execute ───────────────────────
        //
        // This is the mechanism that detects backend intent. The LLM's first
        // action when doing backend work is almost always a `write` (creating a
        // model file) or `bash` (running a migration command). We catch both.
        //
        // Throwing from tool.execute.before cancels the tool call entirely and
        // returns the thrown message as the tool result — the LLM reads it and
        // replans using the BoneScript tools instead.
        "tool.execute.before": async (input, output) => {
            // ── Intercept write calls ──────────────────────────────────────────────
            if (input.tool === "write") {
                const result = classifyWriteCall({
                    filePath: output.args?.filePath,
                    content: output.args?.content,
                });
                if (result.isBackendWork) {
                    // Re-check isBone in case the project was just initialized this session
                    isBone = await isBoneScriptProject(directory);
                    await client.app.log({
                        body: {
                            service: "bonescript-backend-plugin",
                            level: "warn",
                            message: `Intercepted write to backend path: ${output.args?.filePath}`,
                            extra: { reason: result.reason, confidence: result.confidence },
                        },
                    });
                    throw new Error(buildRedirectMessage(isBone, "write", result.reason));
                }
            }
            // ── Intercept bash calls ───────────────────────────────────────────────
            if (input.tool === "bash") {
                const result = classifyBashCall({
                    command: output.args?.command,
                });
                if (result.isBackendWork) {
                    isBone = await isBoneScriptProject(directory);
                    await client.app.log({
                        body: {
                            service: "bonescript-backend-plugin",
                            level: "warn",
                            message: `Intercepted backend bash command: ${output.args?.command}`,
                            extra: { reason: result.reason, confidence: result.confidence },
                        },
                    });
                    throw new Error(buildRedirectMessage(isBone, "bash", result.reason));
                }
            }
        },
        // ── Auto-check on .bone file edits ───────────────────────────────────────
        "file.edited": async ({ file }) => {
            if (!file.endsWith(".bone"))
                return;
            // Re-evaluate project status — a .bone file was just saved
            isBone = true;
            try {
                const result = await $ `bonec check`.cwd(directory).text();
                await client.app.log({
                    body: {
                        service: "bonescript-backend-plugin",
                        level: "info",
                        message: "bonec check passed after file edit",
                        extra: { file, output: result.slice(0, 500) },
                    },
                });
            }
            catch (err) {
                await client.app.log({
                    body: {
                        service: "bonescript-backend-plugin",
                        level: "warn",
                        message: "bonec check found issues after file edit",
                        extra: { file, error: String(err).slice(0, 500) },
                    },
                });
            }
        },
        // ── Inject BoneScript context on session compaction ──────────────────────
        "experimental.session.compacting": async (_input, output) => {
            output.context.push(BONESCRIPT_SYSTEM_PROMPT);
        },
        // ── Inject AGENTS.md guidance when a new session starts ─────────────────
        "session.created": async () => {
            // Always inject guidance — even on non-BoneScript projects, so the agent
            // knows to use bonescript_init if backend work comes up.
            await ensureAgentsMdGuidance(directory);
        },
        // ── Custom tools ─────────────────────────────────────────────────────────
        tool: {
            bonescript_init: bonescriptInitTool,
            bonescript_compile: bonescriptCompileTool,
            bonescript_watch: bonescriptWatchTool,
            bonescript_check: bonescriptCheckTool,
            bonescript_diff: bonescriptDiffTool,
            bonescript_edit: bonescriptEditTool,
            bonescript_implement_extension: bonescriptImplementExtensionTool,
            bonescript_analyze: bonescriptAnalyzeTool,
        },
    };
};
